### Agent Loop: prompt → tool call → result → next prompt

זה ה-core של Claude Code. הלולאה פועלת כך:

```typescript
class ClaudeCodeAgent {
  private model = "claude-3-5-sonnet-20241022";
  private maxIterations = 100;
  private contextManager: ContextManager;
  private toolExecutor: ToolExecutor;

  async run(userPrompt: string): Promise<string> {
    const context = await this.contextManager.initialize();
    let messages: Message[] = [];

    // בנה system prompt מ-CLAUDE.md ו-context
    const systemPrompt = this.buildSystemPrompt(context);

    for (let iteration = 0; iteration < this.maxIterations; iteration++) {
      // שלב 1: קרא ל-Claude
      const response = await this.callClaude(
        systemPrompt,
        messages,
        context
      );

      // שלב 2: בדוק stop reason
      if (response.stop_reason === "end_turn") {
        // Claude סיים — החזר תשובה
        return this.extractText(response.content);
      }

      if (response.stop_reason === "tool_use") {
        // שלב 3: בצע tool use
        const toolUseBlocks = response.content.filter(
          b => b.type === "tool_use"
        );

        // הוסף response של Claude להודעות
        messages.push({
          role: "assistant",
          content: response.content
        });

        // בצע כל tool use
        const toolResults = await Promise.all(
          toolUseBlocks.map(block => 
            this.toolExecutor.execute(block.name, block.input)
          )
        );

        // שלב 4: הוסף תוצאות חזרה
        messages.push({
          role: "user",
          content: toolResults.map((result, i) => ({
            type: "tool_result",
            tool_use_id: toolUseBlocks[i].id,
            content: result
          }))
        });

        // עדכן context
        await this.contextManager.update(messages);
      }
    }

    throw new Error("Max iterations reached");
  }

  private buildSystemPrompt(context: Context): string {
    // קרא CLAUDE.md מהפרויקט
    const claudeMd = context.claudeMd || "";

    // בנה system prompt
    return `You are Claude Code, an AI coding assistant.

${claudeMd}

Available tools:
${this.getToolDefinitions()}

Current project context:
${context.projectSummary}

Guidelines:
- Think step by step
- Use tools to explore and modify code
- Ask for clarification if needed
- Provide explanations for your changes`;
  }
}
```

