### MCP (Model Context Protocol) — אדריכלות

MCP היא פרוטוקול שמאפשר ל-Claude Code להתחבר לשרתים חיצוניים שמספקים כלים וקשר נוסף:

```typescript
interface MCPServer {
  name: string;
  type: "stdio" | "sse" | "websocket";
  command?: string;
  url?: string;
  env?: Record<string, string>;
}

interface MCPClient {
  servers: Map<string, MCPServer>;

  async connectServer(server: MCPServer): Promise<void> {
    // התחבר לשרת MCP
    if (server.type === "stdio") {
      // הרץ תהליך וקרא/כתוב ל-stdin/stdout
      const process = spawn(server.command, {
        env: { ...process.env, ...server.env }
      });

      // שלח initialize message
      process.stdin.write(JSON.stringify({
        jsonrpc: "2.0",
        id: 1,
        method: "initialize",
        params: {
          protocolVersion: "2024-11-05",
          capabilities: {},
          clientInfo: {
            name: "claude-code",
            version: "2.1.88"
          }
        }
      }));
    }
  }

  async callTool(
    serverName: string,
    toolName: string,
    args: Record<string, any>
  ): Promise<any> {
    // קרא לכלי בשרת MCP
    const server = this.servers.get(serverName);
    if (!server) throw new Error(`Server ${serverName} not found`);

    // שלח tool call request
    const response = await this.sendRequest(server, {
      method: "tools/call",
      params: {
        name: toolName,
        arguments: args
      }
    });

    return response.result;
  }
}
```

### Sub-agent Spawning

```typescript
class AgentOrchestrator {
  private agents: Map<string, ClaudeCodeAgent> = new Map();

  async spawnSubAgent(
    role: string,
    task: string,
    parentContext: Context
  ): Promise<string> {
    // יצור agent חדש עם context מוגבל
    const subAgent = new ClaudeCodeAgent();

    // בנה context עבור sub-agent
    const subContext = {
      ...parentContext,
      role: role,
      parentAgentId: parentContext.agentId,
      allowedTools: this.getToolsForRole(role),
      maxTokens: 2000 // הגבל tokens עבור sub-agent
    };

    // הרץ את ה-sub-agent
    const result = await subAgent.run(task);

    // שמור תוצאה
    this.agents.set(subAgent.id, subAgent);

    return result;
  }

  async coordinateMultipleAgents(
    task: string,
    roles: string[]
  ): Promise<any> {
    // פרק משימה לתת-משימות
    const subtasks = await this.decomposeTasks(task, roles);

    // הרץ agents במקביל
    const results = await Promise.all(
      subtasks.map(st => 
        this.spawnSubAgent(st.role, st.task, this.context)
      )
    );

    // אחד תוצאות
    return this.synthesizeResults(results);
  }
}
```

